import json

import boto3

from.embeddings_client import get_bedrock_client
from.embeddings_models import normalize_payload, parse_response


def embedding_job_summary(job_id, config=None):
    config = config or {}
    client = get_bedrock_client(config)
    response = client.get_embedding_job(jobId=job_id)
    job_summary = parse_response(response["body"].read())
    return {"job_summary": job_summary}

import re


def corpus_safety(text):
    if re.search(r"[\p{So}\p{Cn}]", text):
        return {"is_safe": False, "reason": "Text contains special or non-printable characters."}
    return {"is_safe": True}

import boto3


def multilingual_query_translate(query, target_language, config=None):
    config = config or {}
    translate_client = boto3.client('translate', region_name=config.get('region', 'us-east-1'))
    response = translate_client.translate_text(Text=query, SourceLanguageCode='auto', TargetLanguageCode=target_language)
    translated_query = response['TranslatedText']
    return {"translated_query": translated_query}

import boto3


def retrieval_audio_brief(search_results, config=None):
    config = config or {}
    polly_client = boto3.client('polly', region_name=config.get('region', 'us-east-1'))
    speech_text = ' '.join([result['text'] for result in search_results])
    response = polly_client.synthesize_speech(Text=speech_text, OutputFormat='mp3', VoiceId='Joanna')
    audio_stream = response['AudioStream']
    with open('audio_brief.mp3', 'wb') as f:
        f.write(audio_stream.read())
    return {"audio_brief_path": 'audio_brief.mp3'}
